const icon=(name)=>{const i={plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',inbox:'<path d="M4 4h16v12h-4l-2 3h-4l-2-3H4z"/><path d="M4 12h4l2 3h4l2-3h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',alert:'<path d="m10.3 3.9-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3.1l-8-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',spark:'<path d="m12 3 2 6 6 2-6 2-2 6-2-6-6-2 6-2z"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>',download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4m4-5 5 5 5-5m-5 5V3"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',building:'<path d="M3 21h18M5 21V6l7-3 7 3v15M9 9h.01M15 9h.01M9 13h.01M15 13h.01M10 21v-4h4v4"/>',git:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="7" r="2"/><circle cx="8" cy="19" r="2"/><path d="M6 7v4a4 4 0 0 0 4 4h4a4 4 0 0 0 4-4V9M8 17v-2"/>',chart:'<path d="M3 3v18h18M7 14l4-4 4 3 6-7"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2M9.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM20 8v6m3-3h-6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${i[name]||''}</svg>`};
function toast(message){const region=document.querySelector('.toast-region')||(()=>{const n=document.createElement('div');n.className='toast-region';n.setAttribute('aria-live','polite');document.body.append(n);return n})();const t=document.createElement('div');t.className='toast';t.innerHTML=`<b>✓</b>${esc(message)}`;region.append(t);setTimeout(()=>t.remove(),3200)}
function renderHeading(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="page-kicker">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function button(action,text,kind='btn',ic=''){return `<button class="${kind}" data-action="${action}">${ic?icon(ic):''}${text}</button>`}
function statusClass(v){if(/متأخر|تعارض|عاجل|رفض/.test(v))return 'bad';if(/انتظار|متابعة|تنسيق|مراجعة|عالي/.test(v))return 'warn';if(/معتمد|مكتمل|المسار/.test(v))return 'good';return 'info'}
function status(text){return `<span class="status ${statusClass(text)}">${esc(text)}</span>`}
function projectTable(rows){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>المشروع</th><th>العميل</th><th>مدير المشروع</th><th>موعد التسليم</th><th>الإنجاز</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="row-main"><span class="project-mark">${esc(p.code.slice(-3))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${esc(p.location)}</small></span></div></td><td>${esc(p.client)}</td><td>${esc(p.manager)}</td><td>${fmtDate(p.due)}</td><td><div style="display:flex;align-items:center;gap:8px"><span class="progress"><span style="width:${p.progress}%"></span></span><small>${p.progress}%</small></div></td><td>${status(p.status)}</td><td><a class="btn btn-sm btn-icon" href="workspace.html?project=${encodeURIComponent(p.id)}" aria-label="فتح المشروع">${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`}
function activityList(items){return `<div class="activity">${items.slice(0,4).map(a=>`<div class="activity-row"><i class="activity-mark"></i><div><strong>${esc(a.text)}</strong><p>${esc(a.detail)}</p><time>${esc(a.time)}</time></div></div>`).join('')}</div>`}
