function notificationItems(){const s=getState(),user=s.user||{role:'manager',name:''},role=user.role,name=user.name||'';if(role==='client')return s.approvals.filter(a=>a.recipient===name&&a.status==='بانتظار العميل').map(a=>({id:'APR-'+a.id,text:'مراجعة مطلوبة: '+a.title,type:'اعتماد',href:'approvals.html',seen:s.notifications.some(n=>n.id==='APR-'+a.id&&n.seen)}));const tasks=s.tasks.filter(t=>t.assignee===name&&t.status==='متأخرة'),items=s.notifications.filter(n=>{if(role==='engineer'&&n.type==='مهمة')return tasks.length>0;if(role==='engineer'&&n.type==='اعتماد')return false;return true}).map(n=>({...n,href:n.type==='اعتماد'?'approvals.html':n.type==='مهمة'?'tasks.html':'files.html'}));if(role==='manager'||role==='pm'){const requests=(s.clientRequests||[]).filter(r=>r.status==='جديد').map(r=>({id:'REQ-'+r.id,text:'طلب عميل جديد: '+r.title,type:'طلب عميل',href:'client-requests.html',seen:!!r.seen}));return [...requests,...items]}return items}
function renderNotificationPanel(){const panel=$('#notificationsPopover'),button=$('[data-action="notifications"]');if(!panel||!button)return;const items=notificationItems();panel.innerHTML=`<header class="notifications-head"><div><strong>الإشعارات</strong><small>${items.filter(n=>!n.seen).length} غير مقروءة</small></div><button type="button" class="notifications-mark" data-action="notifications-read">تحديد الكل كمقروء</button></header><div class="notifications-list">${items.map(n=>`<a class="notification-item ${n.seen?'':'unread'}" href="${n.href}" data-notification-id="${esc(n.id)}"><i class="notification-kind ${n.type==='اعتماد'?'gold':n.type==='مهمة'?'red':''}"></i><span><b>${esc(n.text)}</b><small>${esc(n.type)}</small></span>${n.seen?'':'<em aria-label="غير مقروء"></em>'}</a>`).join('')||'<div class="notifications-empty"><b>لا توجد إشعارات جديدة</b><small>ستظهر هنا التحديثات المرتبطة بدورك ومشاريعك.</small></div>'}</div>`;panel.hidden=false;button.setAttribute('aria-expanded','true');localizeUi()}
