const translateUiText=(value)=>{const exact=englishText[value.trim()];if(exact)return value.replace(value.trim(),exact);let out=value;for(const [ar,en] of Object.entries(englishText).sort((a,b)=>b[0].length-a[0].length)){if(ar.length>1&&out.includes(ar))out=out.split(ar).join(en)}return out.replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d))};
function localizeUi(){if(getState().settings.language!=='en')return;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest('script,style,svg,[data-no-translate]'))continue;node.nodeValue=translateUiText(node.nodeValue)}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(attr=>{const value=el.getAttribute(attr);if(value)el.setAttribute(attr,translateUiText(value))}));const pageTitle={overview:'Overview',home:'Home',mvp:'Home',projects:'Projects',workspace:'Project workspace',changes:'Engineering changes',thread:'Project links',tasks:'Tasks',files:'Files & revisions',approvals:'Approvals',team:'Team',settings:'Preferences',consultations:'Consultations',client:'Client portal','client-requests':'Client requests',ai:'NAWA assistant',reports:'Reports',decisions:'Engineering decisions',meetings:'Meetings',clients:'Clients',schedule:'Schedule',boq:'Quantities & cost',timeline:'Project history'}[page]||'Workspace';document.title=`${pageTitle} | NAWA`}
function render(){const activeUser=getState().user;if(!activeUser){location.replace('login.html');return}const role=activeUser.role||'manager',allowed={manager:Object.keys(views),pm:['overview','home','mvp','projects','workspace','changes','thread','tasks','files','approvals','team','ai','reports','decisions','meetings','schedule','timeline','client-requests','consultations','settings'],engineer:['overview','home','mvp','projects','workspace','changes','thread','tasks','files','ai','decisions','meetings','timeline','consultations','settings'],client:['client','client-requests','projects','approvals','files','consultations','settings']};if(!((allowed[role]||allowed.manager).includes(page))){location.replace(role==='client'?'client.html':'home.html');return}(views[page]||overview)();document.title=`${({overview:'الرئيسية',home:'الرئيسية',mvp:'الرئيسية',projects:'المشاريع',workspace:'مساحة المشروع',changes:'التغييرات الهندسية',thread:'الخيط الهندسي',tasks:'المهام',files:'الملفات والإصدارات',approvals:'الاعتمادات',team:'الفريق',client:'بوابة العميل',ai:'مساعد نَواة',reports:'التقارير',settings:'إعدادات المكتب',decisions:'القرارات الهندسية',meetings:'الاجتماعات',clients:'العملاء',schedule:'الجدول الزمني',boq:'الكميات والتكلفة',timeline:'سجل المشروع','client-requests':'طلبات العملاء',consultations:'الاستشارات الهندسية'})[page]||'نَواة'} | نَواة`;localizeUi()}
function openModal(title,body,submit='حفظ'){let root=$('#modalBackdrop');if(!root){root=document.createElement('div');root.id='modalBackdrop';root.className='modal-backdrop';root.innerHTML='<section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><h2 id="modalTitle"></h2><button class="modal-close" data-action="close-modal" aria-label="إغلاق">×</button></header><form id="modalForm"><div class="modal-body" id="modalBody"></div><footer class="modal-foot"><button class="btn btn-primary" type="submit" id="modalSubmit"></button><button class="btn" type="button" data-action="close-modal">إلغاء</button></footer></form></section>';document.body.append(root)}$('#modalTitle',root).textContent=title;$('#modalBody',root).innerHTML=body;$('#modalSubmit',root).textContent=submit;root.classList.add('open');localizeUi()}
function modalFor(action,id=''){const s=getState(),projectOptions=s.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');const forms={
'new-project':['إضافة مشروع',`<div class="form-grid"><div class="field full"><label>اسم المشروع</label><input name="name" required placeholder="اسم واضح للمشروع"></div><div class="field"><label>العميل</label><input name="client" required></div><div class="field"><label>المدينة</label><input name="location" value="الرياض"></div><div class="field"><label>الموعد المستهدف</label><input type="date" name="due" required></div><div class="field"><label>نوع المشروع</label><select name="type"><option>مبنى تجاري</option><option>سكني</option><option>مكتبي</option><option>بنية تحتية</option></select></div></div>`],
'new-task':['إضافة مهمة',`<div class="form-grid"><div class="field full"><label>وصف المهمة</label><input name="title" required></div><div class="field"><label>المشروع</label><select name="project">${projectOptions}</select></div><div class="field"><label>التخصص</label><select name="discipline"><option>معماري</option><option>إنشائي</option><option>ميكانيكي</option><option>كهربائي</option><option>كميات</option><option>إدارة المشروع</option></select></div><div class="field"><label>المسؤول</label><select name="assignee">${s.team.map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>الموعد</label><input name="due" type="date" required></div><div class="field"><label>الأولوية</label><select name="priority"><option>متوسطة</option><option>عالية</option><option>عادية</option></select></div></div>`],
'new-change':['تسجيل طلب تغيير',`<div class="form-grid"><div class="field full"><label>عنوان الطلب</label><input name="title" required></div><div class="field"><label>المشروع</label><select name="project">${projectOptions}</select></div><div class="field"><label>مقدم الطلب</label><input name="requester" required></div><div class="field full"><label>وصف التغيير</label><textarea name="description" required></textarea></div><div class="field"><label>التخصصات المتأثرة</label><input name="disciplines" placeholder="معماري، كهربائي"></div><div class="field"><label>الأولوية</label><select name="priority"><option>متوسطة</option><option>عالية</option><option>عادية</option></select></div></div>`],
'new-decision':['توثيق قرار هندسي',`<div class="form-grid"><div class="field"><label>رقم القرار</label><input name="id" placeholder="D-020"></div><div class="field"><label>المشروع</label><select name="project">${projectOptions}</select></div><div class="field full"><label>موضوع القرار</label><input name="title" required></div><div class="field full"><label>المبررات والمراجع</label><textarea name="description" required></textarea></div></div>`],
'upload':['رفع مستند وتحليله',`<div class="form-grid"><div class="field full"><label>الملف</label><input name="file" type="file" required></div><div class="field"><label>المشروع</label><select name="project"><option value="">بدون مشروع محدد</option>${projectOptions}</select></div><div class="field"><label>رقم المستند</label><input name="code" placeholder="A-105"></div><div class="field"><label>التخصص</label><select name="discipline"><option>معماري</option><option>إنشائي</option><option>ميكانيكي</option><option>كهربائي</option><option>كميات</option><option>إدارة المشروع</option></select></div><div class="field full"><div class="notice">يُرفع الملف إلى التخزين الخاص R2 ثم يدخل مسار المعالجة والفهرسة الذكية. الوصول يبقى محكومًا بصلاحيات الحساب والمشروع.</div></div></div>`],
'invite':['إضافة عضو للفريق',`<div class="form-grid"><div class="field"><label>الاسم</label><input name="name" required></div><div class="field"><label>الدور</label><select name="role"><option>مهندس</option><option>مدير مشروع</option><option>عميل</option></select></div><div class="field full"><label>التخصص</label><input name="discipline" required></div><div class="field full"><div class="notice">لن تُرسل دعوة فعلية؛ هذه إضافة محلية لبيانات المعاينة.</div></div></div>`],
'analyze':['تحليل أثر تجريبي · CR-017',`<div class="notice warn"><div><strong>نتيجة محاكاة محلية وليست ذكاءً اصطناعيًا متصلًا.</strong><br>قد يؤثر توسيع الغرفة على المخطط المعماري والتكييف والإنارة والكميات. الأثر الإنشائي غير محسوم ويتطلب مراجعة مهندس.</div></div><h3>المصادر المستخدمة</h3><span class="source-chip">CR-017</span><span class="source-chip">A-104 v3</span><span class="source-chip">M-203 v2</span><span class="source-chip">D-014</span><h3>معلومات مطلوبة</h3><p>الأبعاد النهائية ومراجعة المهندس الإنشائي. لم تُنشأ مهام أو اعتمادات.</p>`],
'approval-detail':['تفاصيل الاعتماد',(()=>{const a=s.approvals.find(x=>x.id===id);return a?`<div class="approval-card"><span class="tag">${esc(a.id)}</span>${status(a.status)}<h3>${esc(a.title)}</h3><p>${esc(projectName(a.project,s))} · ${esc(a.recipient)}</p><div class="detail-row"><span>تاريخ الإرسال</span><b>${fmtDate(a.sent)}</b></div><div class="detail-row"><span>النوع</span><b>${esc(a.type)}</b></div><div class="notice warn">معاينة فقط: لا يوجد إرسال أو اعتماد خارجي مفعّل.</div></div>`:'<p>لم يتم العثور على الاعتماد.</p>'})()],
'report':['ملخص أداء المكتب',`<div class="notice"><div><strong>موجز المكتب · ${fmtDate('2026-10-01')}</strong><br>المشاريع: ${s.projects.length} · المهام: ${s.tasks.length} · التغييرات المفتوحة: ${s.changes.length} · الاعتمادات المنتظرة: ${s.approvals.filter(a=>a.status==='بانتظار العميل').length}.</div></div><p>هذا ملخص توضيحي من بيانات العرض التجريبية.</p>`]};const item=forms[action];if(item){openModal(item[0],item[1],['analyze','approval-detail','report'].includes(action)?'إغلاق':'حفظ');$('#modalForm').dataset.action=action}}
function handleModalSubmit(form){const key=form.dataset.action,data=new FormData(form),v=n=>String(data.get(n)||'').trim();updateState(s=>{if(key==='new-project'){s.projects.unshift({id:makeId('P'),code:`NAWA-${String(s.projects.length+1).padStart(3,'0')}`,name:v('name'),client:v('client'),manager:s.user?.name||'جوري العروي',location:v('location')||'الرياض',type:v('type'),start:new Date().toISOString().slice(0,10),due:v('due'),progress:0,status:'على المسار',team:1,budget:0});s.activity.unshift({text:'أُضيف مشروع جديد',detail:v('name'),time:'الآن'})}if(key==='new-task')s.tasks.unshift({id:makeId('T'),title:v('title'),project:v('project'),discipline:v('discipline'),assignee:v('assignee'),priority:v('priority'),due:v('due'),status:'قائمة المهام',change:''});if(key==='new-change')s.changes.unshift({id:makeId('CR'),title:v('title'),project:v('project'),requester:v('requester'),date:new Date().toISOString().slice(0,10),status:'جديد',priority:v('priority'),description:v('description'),disciplines:v('disciplines').split(/[،,]/).map(x=>x.trim()).filter(Boolean),sources:[]});if(key==='new-decision')s.activity.unshift({text:`تم توثيق القرار ${v('id')||makeId('D')}`,detail:v('title'),time:'الآن'});if(key==='upload')s.files.unshift({id:makeId('F'),name:v('name'),code:v('code'),discipline:v('discipline'),type:v('type'),version:1,updated:new Date().toISOString().slice(0,10),owner:v('owner'),state:'مسودة',refs:[]});if(key==='invite')s.team.unshift({name:v('name'),initial:v('name')[0]||'م',discipline:v('discipline'),role:v('role'),capacity:0,color:'',projects:0});});$('#modalBackdrop')?.classList.remove('open');render();toast('تم الحفظ في بيانات العرض المحلية')}

