document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){const a=action.dataset.action,id=action.dataset.id;if(a==='language-toggle'){updateState(s=>{s.settings.language=s.settings.language==='en'?'ar':'en'});render();return}if(a==='achievement'){const card=e.target.closest('.task-achievement'),detail=card?.querySelector('.achievement-detail'),expanded=e.target.getAttribute('aria-expanded')==='true';if(card&&detail){e.target.setAttribute('aria-expanded',String(!expanded));detail.hidden=expanded;card.classList.toggle('is-expanded',!expanded)}return}if(a==='theme-toggle'){updateState(s=>{s.settings.theme=s.settings.theme==='dark'?'light':'dark'});render();return}if(a==='font-decrease'||a==='font-increase'){const sizes=['small','normal','large'];updateState(s=>{const i=Math.max(0,sizes.indexOf(s.settings.fontSize||'normal'));s.settings.fontSize=sizes[Math.max(0,Math.min(2,i+(a==='font-increase'?1:-1)))]});render();return}if(a==='logout'){updateState(s=>{delete s.user});['nawa-demo-session','nawa-onboarding-role','nawa-onboarding-name','nawa-onboarding-email','nawa-onboarding-office'].forEach(k=>sessionStorage.removeItem(k));location.replace('login.html');return}if(['new-project','new-task','new-change','new-decision','upload','invite','analyze','approval-detail','report'].includes(a)){modalFor(a,id);return}if(a==='close-modal'){$('#modalBackdrop')?.classList.remove('open');return}if(a==='reset-demo'){if(confirm('استعادة بيانات العرض التجريبية؟'))resetState();return}if(a==='consultation-assign'){updateState(s=>{const r=(s.consultations||[]).find(x=>x.id===id);if(r)r.status='قيد التنسيق'});render();toast('تم نقل الاستشارة إلى قيد التنسيق');return}if(a==='request-review'){ updateState(s=>{const r=(s.clientRequests||[]).find(x=>x.id===id);if(r)r.status='قيد المراجعة'});render();toast('تم نقل الطلب إلى قيد المراجعة');return}if(a==='task-done'){ updateState(s=>{const t=s.tasks.find(x=>x.id===id);if(t)t.status='مكتملة'});render();toast('أُغلقت المهمة في العرض');return}if(a==='clear-chat'){$('#chatMessages').innerHTML='<div class="msg ai">بدأت محادثة جديدة. اسأليني عن بيانات المشروع التجريبية.<small>المصدر: بيانات مساحة العرض</small></div>';return}if(a==='remind'){toast('تم تجهيز تذكير للمعاينة فقط؛ لم يُرسل للعميل');return}if(a==='notifications'){const panel=$('#notificationsPopover');if(panel&&!panel.hidden)closeNotificationPanel();else renderNotificationPanel();return}if(a==='notifications-read'){updateState(s=>{const ids=notificationItems().map(n=>n.id);s.notifications.forEach(n=>{if(ids.includes(n.id)||n.id.startsWith('N-'))n.seen=true});notificationItems().filter(n=>n.id.startsWith('APR-')).forEach(n=>{if(!s.notifications.some(x=>x.id===n.id))s.notifications.push({id:n.id,text:n.text,type:n.type,seen:true})});notificationItems().filter(n=>n.id.startsWith('REQ-')).forEach(n=>{const r=(s.clientRequests||[]).find(x=>'REQ-'+x.id===n.id);if(r)r.seen=true})});renderNotificationPanel();return}if(a==='menu'){document.body.classList.toggle('menu-open');return}if(a==='close-menu'){document.body.classList.remove('menu-open');return}if(a==='office-switch'){toast('مساحة المكتب الحالية: '+getState().settings.office);return}if(a==='file-detail'){e.preventDefault();const f=getState().files.find(x=>x.id===id);if(f){openModal(f.name,`<span class="tag">${esc(f.code)}</span><div class="detail-row"><span>الإصدار</span><b>v${f.version}</b></div><div class="detail-row"><span>التخصص والمالك</span><b>${esc(f.discipline)} · ${esc(f.owner)}</b></div><div class="detail-row"><span>الحالة</span>${status(f.state)}</div><div class="notice">${(f.refs||[]).length?'المراجع المرتبطة: '+f.refs.map(esc).join('، '):'لا توجد روابط مسجلة.'}</div>`,'إغلاق')}return}if(a==='export'){toast('تصدير القوائم غير مفعّل في نموذج المعاينة');return}if(a==='view-member'||a==='reassign'){toast('هذه الميزة قيد التجهيز في نموذج العرض');return}}
const node=e.target.closest('.thread-node');if(node){const labels={'CR-017':['طلب العميل · CR-017','توسيع غرفة الاجتماعات 03','زيادة المساحة ترتبط بمراجعة المخطط المعماري والتكييف والإنارة والكميات.'],'R-012':['متطلب · R-012','سعة الغرفة 24 شخصًا','متطلب موثق في سجل المشروع ويرتبط بطلب التغيير.'],'D-014':['قرار هندسي · D-014','موافقة مبدئية','يلزم استكمال مراجعة التخصصات قبل إغلاق التغيير.'],'CHG-0042':['تغيير هندسي','قيد تنسيق التخصصات','يشمل التغيير تحديث المخططات والمراجع التابعة.'],'ARCH-031':['مهمة','تحديث المخطط المعماري','المسؤول: سارة الحربي · مرتبطة بالتغيير CR-017.'],'A-104 v3':['ملف معماري','A-104 · v3','آخر إصدار معماري مسجل في مساحة العرض.'],'M-203 v2':['مرجع ميكانيكي','M-203 · v2','يشير إلى إصدار معماري أقدم ويحتاج مزامنة.'],'APR-008':['اعتماد العميل','APR-008','بانتظار رد العميل على المخطط المعماري A-104 v3.']},d=labels[node.dataset.node]||labels['CR-017'];$$('.thread-node').forEach(n=>n.classList.toggle('selected',n===node));$('#threadDetail').innerHTML=`<span class="page-kicker">${esc(d[0])}</span><h2>${esc(d[1])}</h2><p>${esc(d[2])}</p><div class="detail-row"><span>المشروع</span><b>مركز الرياض للأعمال</b></div><div class="detail-row"><span>الحالة</span>${status(node.dataset.node==='M-203 v2'?'مرجع قديم':'قيد المتابعة')}</div><hr class="section-divider"><b style="font-size:9px">المراجع المرتبطة</b><div><span class="source-chip">CR-017</span><span class="source-chip">A-104 v3</span><span class="source-chip">M-203 v2</span></div><div class="notice warn" style="margin-top:12px">راجع سجل المصدر قبل اتخاذ قرار هندسي.</div>`;return}
const suggestion=e.target.closest('.suggestion');if(suggestion){$('#chatInput').value=suggestion.dataset.question||suggestion.textContent;$('#chatInput').focus()}});
document.addEventListener('submit',e=>{if(e.target.id==='consultationRequestForm'){e.preventDefault();const d=new FormData(e.target),state=getState(),user=state.user||{},role=user.role,project=state.projects.find(p=>p.id===d.get('project')),allowed=project&&(role==='manager'||role==='client'&&project.client===user.name||role==='pm'&&project.manager===user.name||role==='engineer'&&state.tasks.some(t=>t.project===project.id&&t.assignee===user.name));if(!allowed){toast('المشروع غير مرتبط بصلاحية حسابك');return}const row={id:makeId('CON'),project:project.id,requester:state.user?.name||'مستخدم',specialty:String(d.get('specialty')||''),title:String(d.get('title')||'').trim(),description:String(d.get('description')||'').trim(),date:new Date().toISOString().slice(0,10),status:'جديد'};if(!row.title||!row.description)return;updateState(st=>{st.consultations=st.consultations||[];st.consultations.unshift(row);st.activity.unshift({text:'وصل طلب استشارة جديد',detail:row.id+' · '+row.title,time:'الآن'})});toast('تم تسجيل طلب الاستشارة في المعاينة');render();return}if(e.target.id==='clientRequestForm'){e.preventDefault();const d=new FormData(e.target),s=getState(),project=s.projects.find(p=>p.id===d.get('project')&&p.client===s.user?.name);if(!project){toast('تعذر التحقق من المشروع المرتبط بحسابك');return}const req={id:makeId('REQ'),project:project.id,client:project.client,requester:s.user?.name||project.client,type:String(d.get('type')||''),title:String(d.get('title')||'').trim(),description:String(d.get('description')||'').trim(),date:new Date().toISOString().slice(0,10),status:'جديد'};if(!req.title||!req.description)return;updateState(st=>{st.clientRequests=st.clientRequests||[];st.clientRequests.unshift(req);st.activity.unshift({text:'وصل طلب جديد من العميل',detail:req.id+' · '+req.title,time:'الآن'})});toast('تم تسجيل طلبك في بيانات المعاينة');render();return}if(e.target.id==='modalForm'){e.preventDefault();if(['analyze','approval-detail','report'].includes(e.target.dataset.action)){$('#modalBackdrop').classList.remove('open');return}handleModalSubmit(e.target);return}if(e.target.id==='settingsForm'){e.preventDefault();const d=new FormData(e.target);updateState(s=>{if(d.has('office'))s.settings.office=d.get('office');if(d.has('project'))s.settings.project=d.get('project');s.settings.currency=d.get('currency')||s.settings.currency;if(d.has('theme'))s.settings.theme=d.get('theme');if(d.has('language'))s.settings.language=d.get('language');if(d.has('fontSize'))s.settings.fontSize=d.get('fontSize')});toast('حُفظت إعدادات مساحة العمل');render();return}if(e.target.id==='chatForm'){e.preventDefault();const input=$('#chatInput'),q=input.value.trim();if(!q)return;const box=$('#chatMessages');box.insertAdjacentHTML('beforeend',`<div class="msg user">${esc(q)}</div>`);input.value='';let ans='لا أجد سجلًا كافيًا للإجابة. اسألي عن CR-017 أو A-104 أو الاعتمادات.';let src='بيانات مساحة العرض';if(/تعارض|إصدار|تكييف/.test(q)){ans='يوجد تعارض مرجعي واحد: M-203 v2 يشير إلى A-104 v2، بينما أحدث إصدار معماري مسجل هو A-104 v3. يلزم تنسيق الفريق قبل الإغلاق.';src='M-203 v2 · A-104 v3'}else if(/اعتماد|عميل/.test(q)){ans='يوجد طلبان بانتظار العميل: مخطط A-104 v3 لمركز الرياض، وتقرير تقدم سبتمبر لفيلا الروضة.';src='APR-008 · APR-009'}else if(/cr-017|أثر|غرفة/.test(q)){ans='CR-017 يطلب توسيع غرفة الاجتماعات 03 بنسبة 20٪. قد يتأثر المخطط والتكييف والإنارة والكميات، أما الأثر الإنشائي فيحتاج مراجعة.';src='CR-017 · A-104 v3 · M-203 v2'}else if(/مهمة|تأخير/.test(q)){ans=`هناك ${getState().tasks.filter(t=>t.status==='متأخرة').length} مهام متأخرة في بيانات العرض. لوحة المهام للمسؤولين والمواعيد.`;src='سجل المهام'}setTimeout(()=>{box.insertAdjacentHTML('beforeend',`<div class="msg ai">${esc(ans)}<small>إجابة محاكاة · المصادر: ${esc(src)}</small></div>`);box.scrollTop=box.scrollHeight},180);box.scrollTop=box.scrollHeight}});

$('#globalSearch')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase(),box=$('#searchResults');if(!q){box.innerHTML='';box.classList.remove('open');return}const s=getState(),matches=[...s.projects.map(p=>({label:p.name,detail:p.code,url:`workspace.html?project=${p.id}`})),...s.files.map(f=>({label:f.name,detail:f.code,url:'files.html'})),...s.changes.map(c=>({label:c.title,detail:c.id,url:'changes.html'}))].filter(x=>(x.label+' '+x.detail).toLowerCase().includes(q)).slice(0,6);box.innerHTML=matches.map(x=>`<a href="${x.url}"><strong>${esc(x.label)}</strong><small>${esc(x.detail)}</small></a>`).join('')||'<div class="empty-state">لا توجد نتائج مطابقة</div>';box.classList.add('open');localizeUi()});
const filterProjects=()=>$$('.project-list>a').forEach(r=>r.hidden=!(r.textContent.toLowerCase().includes(($('#projectFilter')?.value||'').toLowerCase())&&(!$('#projectStatus')?.value||r.textContent.includes($('#projectStatus').value))));$('#projectFilter')?.addEventListener('input',filterProjects);
$('#projectStatus')?.addEventListener('change',filterProjects);
$('#taskFilter')?.addEventListener('input',e=>$$('.task-card').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
$('#taskProject')?.addEventListener('change',e=>location.href=e.target.value?`tasks.html?project=${e.target.value}`:'tasks.html');
$('#fileFilter')?.addEventListener('input',e=>$$('.file-list>a').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
$('#fileDiscipline')?.addEventListener('change',e=>$$('.file-list>a').forEach(r=>r.hidden=!!e.target.value&&!r.textContent.includes(e.target.value)));
document.addEventListener('click',e=>{if(e.target.id==='modalBackdrop')e.target.classList.remove('open')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#modalBackdrop')?.classList.remove('open');document.body.classList.remove('menu-open')}});

document.addEventListener('click',e=>{if(!e.target.closest('.notification-wrap'))closeNotificationPanel()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNotificationPanel()});
